const H = params.height;
const r = H * 0.115;
const stone = { preset: 'stone', color: '#777b83', roughness: 0.92, flatShading: true };
const darkStone = { preset: 'stone', color: '#4d5159', roughness: 0.95, flatShading: true };
const trim = { preset: 'stone', color: '#9a968d', roughness: 0.88, flatShading: true };
const wood = { preset: 'wood', color: '#4a2f25', roughness: 0.82 };
const metal = { preset: 'metal', color: '#252b35', metalness: 0.65, roughness: 0.42 };
const windowMat = { preset: 'glass', color: '#79c9e8', emissive: '#4da6d8', emissiveIntensity: 1.2, opacity: 0.88 };
const starMat = { preset: 'emissive', color: '#f4df91', emissive: '#ffe9a3', emissiveIntensity: 3 };
const levels = 7;
const bodyH = H * 0.61;
const segH = bodyH / levels;
function lean(y) {
  const q = y / bodyH;
  return [r * (0.42 * q + 0.12 * Math.sin(q * Math.PI * 1.7)), r * (0.18 * q - 0.1 * Math.sin(q * Math.PI * 2.1))];
}
api.add(api.cylinder(r * 1.2, r * 1.28, H * 0.055, 14).translate(0, H * 0.0275, 0), darkStone);
api.add(api.cylinder(r * 1.08, r * 1.18, H * 0.035, 14).translate(0, H * 0.072, 0), trim);
for (let i = 0; i < levels; i++) {
  const y = H * 0.075 + segH * (i + 0.5);
  const p = lean(y);
  const rb = r * (1 - i * 0.025);
  const rt = r * (0.975 - i * 0.025);
  const course = api.cylinder(rt, rb, segH * 1.035, 14).translate(p[0], y, p[1]);
  course.vertexColor((x, yy, z) => api.mix('#656a72', '#94928b', 0.38 + 0.22 * api.noise3(x * 3.2, yy * 2.4, z * 3.2)));
  api.add(course, stone);
  if (i > 0) api.add(api.torus(rb * 0.99, H * 0.008).rotate(90, 0, 0).translate(p[0], y - segH * 0.49, p[1]), darkStone);
  api.collider({ kind: 'cylinder', radius: rb, halfHeight: segH * 0.51, offset: [p[0], y, p[1]] });
}
const doorY = H * 0.16;
api.add(api.box(r * 0.48, H * 0.19, r * 0.09).translate(0, doorY, r * 1.12), wood);
api.add(api.torus(r * 0.29, H * 0.025).translate(0, doorY + H * 0.06, r * 1.17), trim);
for (let n = 0; n < 7; n++) {
  const y = H * (0.23 + n * 0.052);
  const p = lean(y);
  const a = (n * 137 + 28) * Math.PI / 180;
  const rr = r * (1.015 - n * 0.018);
  const wx = p[0] + Math.sin(a) * rr;
  const wz = p[1] + Math.cos(a) * rr;
  api.add(api.box(r * 0.3, H * 0.075, H * 0.018).rotate(0, a * 180 / Math.PI, 0).translate(wx, y, wz), windowMat);
  api.add(api.torus(r * 0.19, H * 0.018).rotate(0, a * 180 / Math.PI, 0).translate(wx, y + H * 0.012, wz), trim);
  api.add(api.box(H * 0.014, H * 0.066, H * 0.023).rotate(0, a * 180 / Math.PI, 0).translate(wx, y, wz), metal);
}
const topY = H * 0.075 + bodyH;
const topP = lean(bodyH);
const balconyY = topY - H * 0.035;
api.add(api.cylinder(r * 1.48, r * 1.42, H * 0.045, 18).translate(topP[0], balconyY, topP[1]), trim);
api.add(api.torus(r * 1.43, H * 0.025).rotate(90, 0, 0).translate(topP[0], balconyY + H * 0.035, topP[1]), metal);
for (let i = 0; i < 12; i++) {
  const a = i * Math.PI * 2 / 12;
  const x = topP[0] + Math.cos(a) * r * 1.43;
  const z = topP[1] + Math.sin(a) * r * 1.43;
  api.add(api.box(H * 0.018, H * 0.105, H * 0.018).translate(x, balconyY + H * 0.085, z), metal);
}
api.add(api.torus(r * 1.43, H * 0.021).rotate(90, 0, 0).translate(topP[0], balconyY + H * 0.14, topP[1]), metal);
const roofBase = topY + H * 0.005;
const roofH = H * 0.285;
api.add(api.cone(r * 1.42, roofH, 18).translate(topP[0], roofBase + roofH * 0.5, topP[1]), { preset: 'fabric', color: params.roofColor, roughness: 0.72, flatShading: true });
api.add(api.torus(r * 1.38, H * 0.025).rotate(90, 0, 0).translate(topP[0], roofBase + H * 0.018, topP[1]), metal);
for (let i = 0; i < 22; i++) {
  const f = 0.12 + api.rng() * 0.7;
  const a = api.rng() * Math.PI * 2;
  const rad = r * 1.42 * (1 - f) + H * 0.012;
  const x = topP[0] + Math.cos(a) * rad;
  const z = topP[1] + Math.sin(a) * rad;
  const y = roofBase + roofH * f;
  api.add(api.sphere(H * (0.009 + api.rng() * 0.004), 0).translate(x, y, z), starMat);
}
const orbY = roofBase + roofH + H * 0.045;
api.add(api.cylinder(H * 0.018, H * 0.022, H * 0.07, 8).translate(topP[0], roofBase + roofH + H * 0.015, topP[1]), metal);
api.add(api.sphere(H * 0.047, 2).translate(topP[0], orbY, topP[1]), { preset: 'crystal', color: '#b7f1ff', emissive: '#69dfff', emissiveIntensity: 4, roughness: 0.12 });
api.collider({ kind: 'cylinder', radius: r * 1.48, halfHeight: H * 0.025, offset: [topP[0], balconyY, topP[1]] });
return api.build();
